export type Bookmark = {
  id: string;
  title: string;
  url: string;
  hostname: string;
  favicon: Blob | null;
  description: string;
  tags: string[];
  isPinned: boolean;
  isArchived: boolean;
  visitCount: number;
  createdAt: number;
  visitedAt: number | null;
};

export const tabOptions = ["Home", "Archived"] as const;
export type TabOption = (typeof tabOptions)[number];

export const sortOptions = ["Recently Added", "Recently Visited", "Most Visited"] as const;
export type SortOption = (typeof sortOptions)[number];

export const db = new Dexie("BookmarkDB") as Dexie & {
  bookmarks: EntityTable<Bookmark, "id">;
};

db.version(1).stores({
  bookmarks: "id, createdAt, visitCount",
});

let &[tagCounts] = track(() => {
  const counts: Record<string, number> = {};
  [...data.values()].forEach((bookmark) => {
    bookmark.tags.forEach((tag) => (counts[tag] = (counts[tag] ?? 0) + 1));
  });

  return Object.fromEntries(Object.entries(counts).sort(([a], [b]) => a.localeCompare(b)));
});

return [...data.values()].filter((bookmark) => {
  if (bookmark.isArchived !== (_tab === "Archived")) return false;
  if (_tags.length > 0 && !_tags.every((t) => bookmark.tags.includes(t))) return false;
  if (_search && !bookmark.title.toLowerCase().includes(_search)) return false;
  return true;

}).sort((a, b) => {
  if (a.isPinned !== b.isPinned) return a.isPinned ? -1 : 1;

  if (_sort === "Recently Visited") {
    const diff = (b.visitedAt ?? 0) - (a.visitedAt ?? 0);
    if (diff !== 0) return diff;
  } else if (_sort === "Most Visited") {
    const diff = b.visitCount - a.visitCount;
    if (diff !== 0) return diff;
  }

  // Fallback: recently added
  return b.createdAt - a.createdAt;
});

